// À ADAPTER : les seuls réglages du workflow. Le jeton reste « change-moi » dans le fichier
// commité ; mettez la valeur d'API_TOKEN dans n8n. Workflow d'erreur : à choisir dans Settings → Error workflow de chaque workflow 05 à 11.
const parametres = {
  valideur: 'votre.adresse@gmail.com',             // reçoit les alertes et les dossiers à valider
  expediteur: 'Copilote IFRS 17 <votre.adresse@gmail.com>',  // l'adresse du compte SMTP
  api: 'http://127.0.0.1:8000',
  jeton: 'change-moi',
};
const e = $input.first().json;
return [{ json: { parametres,
  sujet: `IFRS 17 · alerte n8n · ${e.workflow?.name ?? 'workflow inconnu'}`,
  texte: [
    `Workflow : ${e.workflow?.name ?? '?'} (id ${e.workflow?.id ?? '?'})`,
    `Nœud en échec : ${e.execution?.lastNodeExecuted ?? '?'}`,
    `Erreur : ${e.execution?.error?.message ?? e.trigger?.error?.message ?? '?'}`,
    `Exécution : ${e.execution?.url ?? '(pas d\'URL : exécution manuelle)'}`,
    `Mode : ${e.execution?.mode ?? '?'}`,
    '', 'Vérifier l\'API (page /health) et les identifiants SMTP/IMAP, puis relancer l\'exécution depuis n8n.',
  ].join('\n') } }];
